task.vi:
Cài đặt hàm kiểm tra xem mảng hai chiều có chứa 4 số liên tiếp có cùng giá trị theo hàng ngang, cột dọc hoặc đường chéo hay không:
  bool isConsecutiveFour(int values[][7]);
Viết chương trình kiểm tra yêu cầu người dùng nhập số hàng và số cột (với cột cố định là 7 hoặc tổng quát) cùng các phần tử của mảng hai chiều, sau đó hiển thị true nếu tìm thấy 4 số liên tiếp bằng nhau, ngược lại hiển thị false.

task.en:
Write the function testing whether a 2D array contains four consecutive numbers of equal value horizontally, vertically, or diagonally:
  bool isConsecutiveFour(int values[][7]);
Write a test program that prompts the user to enter the dimensions and elements of the 2D array, then displays true if it contains four consecutive equal values, or false otherwise.

task.vi:
Một ma trận vuông n * n được gọi là ma trận Markov dương nếu mọi phần tử trong ma trận đều dương (> 0) và tổng các phần tử trong mỗi cột đều bằng 1. Viết hàm kiểm tra ma trận Markov:
  const int SIZE = 3;
  bool isMarkovMatrix(const double m[][SIZE]);
Viết chương trình kiểm tra cho phép người dùng nhập ma trận 3x3 số thực và in ra ma trận đó có phải là ma trận Markov hay không.

task.en:
An n * n matrix is called a positive Markov matrix if each element is strictly positive and the sum of elements in each column is 1. Write the function:
  const int SIZE = 3;
  bool isMarkovMatrix(const double m[][SIZE]);
Write a test program prompting the user for a 3x3 matrix of double values and testing whether it is a Markov matrix.

example.code:
#include <iostream>
#include <vector>

bool hasConsecutiveFour(const std::vector<std::vector<int>>& grid) {
    int rows = static_cast<int>(grid.size());
    if (rows == 0) return false;
    int cols = static_cast<int>(grid[0].size());

    // 4 directions: horizontal, vertical, diagonal-down-right, diagonal-down-left
    const int dr[4] = {0, 1, 1, 1};
    const int dc[4] = {1, 0, 1, -1};

    for (int r = 0; r < rows; ++r) {
        for (int c = 0; c < cols; ++c) {
            int val = grid[r][c];
            if (val == 0) continue;

            for (int d = 0; d < 4; ++d) {
                int endR = r + 3 * dr[d];
                int endC = c + 3 * dc[d];
                if (endR >= 0 && endR < rows && endC >= 0 && endC < cols) {
                    bool match = true;
                    for (int step = 1; step < 4; ++step) {
                        if (grid[r + step * dr[d]][c + step * dc[d]] != val) {
                            match = false;
                            break;
                        }
                    }
                    if (match) return true;
                }
            }
        }
    } 
    return false;
}

int main() {
    int r = 6, c = 7;
    if (!(std::cin >> r >> c)) return 0;
    std::vector<std::vector<int>> matrix(r, std::vector<int>(c));
    for (int i = 0; i < r; ++i) {
        for (int j = 0; j < c; ++j) {
            std::cin >> matrix[i][j];
        }
    }

    std::cout << std::boolalpha << hasConsecutiveFour(matrix) << "\n";
    return 0;
}

#include <iostream>
#include <vector>
#include <iomanip>

void detectUnsafeBanks(int n, double limit,
                       const std::vector<double>& balances,
                       std::vector<std::vector<double>>& loan) {
    std::vector<bool> unsafe(n, false);
    bool changed = true;

    while (changed) {
        changed = false;
        for (int i = 0; i < n; ++i) {
            if (unsafe[i]) continue;
            double totalAsset = balances[i];
            for (int j = 0; j < n; ++j) {
                totalAsset += loan[i][j];
            }
            if (totalAsset < limit) {
                unsafe[i] = true;
                changed = true;
                // Bank i defaults: other banks cannot recover loans to i
                for (int lender = 0; lender < n; ++lender) {
                    loan[lender][i] = 0.0;
                }
            }
        }
    }

    std::cout << "Unsafe banks are";
    for (int i = 0; i < n; ++i) {
        if (unsafe[i]) {
            std::cout << " " << i;
        }
    }
    std::cout << "\n";
}

int main() {
    int n;
    double limit;
    if (!(std::cin >> n >> limit)) return 0;

    std::vector<double> balances(n);
    std::vector<std::vector<double>> loan(n, std::vector<double>(n, 0.0));

    for (int i = 0; i < n; ++i) {
        int borrowers;
        std::cin >> balances[i] >> borrowers;
        for (int b = 0; b < borrowers; ++b) {
            int borrowerId;
            double amount;
            std::cin >> borrowerId >> amount;
            loan[i][borrowerId] = amount;
        }
    }

    detectUnsafeBanks(n, limit, balances, loan);
    return 0;
}
